import React from 'react';
import {
  Box,
  Container,
  Typography,
  Grid,
  Link,
  IconButton,
} from '@mui/material';
import {
  Facebook,
  Twitter,
  Instagram,
  LocalDining,
} from '@mui/icons-material';

const Footer: React.FC = () => {
  return (
    <Box
      component="footer"
      sx={{
        backgroundColor: 'primary.dark',
        color: 'white',
        py: 6,
        mt: 'auto',
      }}
    >
      <Container maxWidth="lg">
        <Grid container spacing={4}>
          <Grid item xs={12} sm={6} md={3}>
            <Box sx={{ display: 'flex', alignItems: 'center', mb: 2 }}>
              <LocalDining sx={{ mr: 1, fontSize: 28 }} />
              <Typography variant="h6" sx={{ fontFamily: 'cursive', fontWeight: 700 }}>
                FreshDairy
              </Typography>
            </Box>
            <Typography variant="body2" sx={{ mb: 2, opacity: 0.8 }}>
              Your trusted source for fresh, organic dairy products. 
              Quality you can taste, freshness you can trust.
            </Typography>
            <Box>
              <IconButton sx={{ color: 'white', p: 0.5 }}>
                <Facebook />
              </IconButton>
              <IconButton sx={{ color: 'white', p: 0.5 }}>
                <Twitter />
              </IconButton>
              <IconButton sx={{ color: 'white', p: 0.5 }}>
                <Instagram />
              </IconButton>
            </Box>
          </Grid>

          <Grid item xs={12} sm={6} md={3}>
            <Typography variant="h6" gutterBottom>
              Quick Links
            </Typography>
            <Box>
              <Link href="/" color="inherit" sx={{ display: 'block', mb: 1, opacity: 0.8 }}>
                Home
              </Link>
              <Link href="/products" color="inherit" sx={{ display: 'block', mb: 1, opacity: 0.8 }}>
                Products
              </Link>
              <Link href="/about" color="inherit" sx={{ display: 'block', mb: 1, opacity: 0.8 }}>
                About Us
              </Link>
              <Link href="/contact" color="inherit" sx={{ display: 'block', mb: 1, opacity: 0.8 }}>
                Contact
              </Link>
            </Box>
          </Grid>

          <Grid item xs={12} sm={6} md={3}>
            <Typography variant="h6" gutterBottom>
              Categories
            </Typography>
            <Box>
              <Link href="/products?category=milk" color="inherit" sx={{ display: 'block', mb: 1, opacity: 0.8 }}>
                Milk
              </Link>
              <Link href="/products?category=cheese" color="inherit" sx={{ display: 'block', mb: 1, opacity: 0.8 }}>
                Cheese
              </Link>
              <Link href="/products?category=yogurt" color="inherit" sx={{ display: 'block', mb: 1, opacity: 0.8 }}>
                Yogurt
              </Link>
              <Link href="/products?category=butter" color="inherit" sx={{ display: 'block', mb: 1, opacity: 0.8 }}>
                Butter
              </Link>
            </Box>
          </Grid>

          <Grid item xs={12} sm={6} md={3}>
            <Typography variant="h6" gutterBottom>
              Contact Info
            </Typography>
            <Typography variant="body2" sx={{ mb: 1, opacity: 0.8 }}>
              📧 info@freshdairy.com
            </Typography>
            <Typography variant="body2" sx={{ mb: 1, opacity: 0.8 }}>
              📞 +1 (555) 123-4567
            </Typography>
            <Typography variant="body2" sx={{ mb: 1, opacity: 0.8 }}>
              📍 123 Farm Road, Dairy Valley, CA 90210
            </Typography>
          </Grid>
        </Grid>

        <Box
          sx={{
            borderTop: '1px solid rgba(255,255,255,0.2)',
            mt: 4,
            pt: 4,
            textAlign: 'center',
          }}
        >
          <Typography variant="body2" sx={{ opacity: 0.8 }}>
            © 2024 FreshDairy. All rights reserved. Made with ❤️ for fresh dairy lovers.
          </Typography>
        </Box>
      </Container>
    </Box>
  );
};

export default Footer;
